// Claude Code permission rules (allow / ask / deny in settings.json), managed by
// Kitroom and generated by rulesync's `permissions` feature:
//
//   ~/.kitroom/source/permissions.jsonc   { "permission": { "<category>": { "<pattern>": "allow" | "ask" | "deny" } } }
//
// The app shows entries the way settings.json writes them (`Bash(git push:*)`).
// rulesync maps them to categories (`bash` → `Bash`) and writes the pattern as is.
// On apply it replaces the entries of the categories Kitroom manages and keeps
// every other entry and every other key of settings.json.
//
// Claude Code only for now: rulesync's Codex conversion changes Codex's sandbox
// profile, which needs checking against a real install first (issue #49).
import { rm } from "node:fs/promises";
import { join } from "node:path";
import { PERMISSION_ACTIONS, type ManagedPermissions, type PermissionAction } from "@kitroom/model";
import { claudePaths } from "../claude/paths";
import { Reader } from "../shared/read-utils";
import type { PathContext } from "../types";
import { forgePaths, writeFileAtomic } from "./store";

/** Same tables as rulesync (claudecode permissions). */
const CANONICAL_TO_CLAUDE: Record<string, string> = {
  bash: "Bash",
  read: "Read",
  edit: "Edit",
  write: "Write",
  webfetch: "WebFetch",
  websearch: "WebSearch",
  grep: "Grep",
  glob: "Glob",
  notebookedit: "NotebookEdit",
  agent: "Agent",
};
const CLAUDE_TO_CANONICAL = Object.fromEntries(Object.entries(CANONICAL_TO_CLAUDE).map(([k, v]) => [v, k]));
/** rulesync writes path rules of these tools under another tool's name. */
const PATH_RULE_ALIASES: Record<string, string> = { Write: "Edit", NotebookEdit: "Edit", Glob: "Read" };
const UNSAFE_KEYS = new Set(["__proto__", "constructor", "prototype"]);

export function permissionsPath(ctx: PathContext): string {
  return join(forgePaths(ctx).source, "permissions.jsonc");
}

/** settings.json of the current scope (shared project file, never settings.local.json). */
export function claudeSettingsPath(ctx: PathContext): string {
  return ctx.project ? claudePaths(ctx).project.settings : claudePaths(ctx).global.settings;
}

/** `Tool` or `Tool(pattern)` → tool and pattern (`*` = the whole tool). */
export function parsePermission(entry: string): { tool: string; pattern: string } | null {
  const m = /^([A-Za-z0-9_*-]+)(?:\(([\s\S]*)\))?$/.exec(entry.trim());
  if (!m) return null;
  const pattern = m[2] ?? "*";
  if (m[2] !== undefined && !pattern.trim()) return null;
  return { tool: m[1]!, pattern };
}

const categoryOf = (tool: string) => CLAUDE_TO_CANONICAL[tool] ?? tool;

/** The entry rulesync writes for a category and pattern. */
function claudeEntry(category: string, pattern: string): string {
  const tool = CANONICAL_TO_CLAUDE[category] ?? category;
  if (pattern === "*") return tool;
  return `${PATH_RULE_ALIASES[tool] ?? tool}(${pattern})`;
}

/** Why an entry cannot be managed as written, or null. rulesync would write it differently. */
export function permissionProblem(entry: string): "invalid" | "rewritten" | null {
  const p = parsePermission(entry);
  if (!p || UNSAFE_KEYS.has(p.tool) || UNSAFE_KEYS.has(p.pattern)) return "invalid";
  return claudeEntry(categoryOf(p.tool), p.pattern) === entry.trim() ? null : "rewritten";
}

export async function readManagedPermissions(ctx: PathContext): Promise<ManagedPermissions | null> {
  const r = new Reader();
  const data = (await r.json(permissionsPath(ctx))) as { permission?: Record<string, Record<string, string>> } | undefined;
  if (!data) return null;
  const out: ManagedPermissions = { allow: [], ask: [], deny: [] };
  for (const [category, rules] of Object.entries(data.permission ?? {})) {
    for (const [pattern, action] of Object.entries(rules ?? {})) {
      if ((PERMISSION_ACTIONS as readonly string[]).includes(action)) out[action as PermissionAction].push(claudeEntry(category, pattern));
    }
  }
  return out;
}

/** Validates and stores the rules. An entry may appear in one list only. */
export async function saveManagedPermissions(ctx: PathContext, input: ManagedPermissions): Promise<ManagedPermissions> {
  const permission: Record<string, Record<string, PermissionAction>> = {};
  const seen = new Map<string, PermissionAction>();
  const clean: ManagedPermissions = { allow: [], ask: [], deny: [] };
  for (const action of PERMISSION_ACTIONS) {
    for (const raw of input[action] ?? []) {
      const entry = String(raw).trim();
      if (!entry) continue;
      const problem = permissionProblem(entry);
      if (problem === "invalid") throw new Error(`"${entry}" is not a permission rule. Write Tool or Tool(pattern), e.g. Bash(npm test:*).`);
      const p = parsePermission(entry)!;
      if (problem === "rewritten") throw new Error(`"${entry}" would be written as "${claudeEntry(categoryOf(p.tool), p.pattern)}". Use that form.`);
      const prev = seen.get(entry);
      if (prev === action) continue;
      if (prev) throw new Error(`"${entry}" is in both ${prev} and ${action}. Keep it in one list.`);
      seen.set(entry, action);
      (permission[categoryOf(p.tool)] ??= {})[p.pattern] = action;
      clean[action].push(entry);
    }
  }
  await writeFileAtomic(permissionsPath(ctx), `${JSON.stringify({ permission }, null, 2)}\n`);
  return clean;
}

/** Stops managing permissions. settings.json is left as it is. */
export async function unmanagePermissions(ctx: PathContext): Promise<void> {
  await rm(permissionsPath(ctx), { force: true });
}

/**
 * invalid: not `Tool(pattern)`; rewritten: rulesync would write it differently;
 * conflict: in more than one list; same-tool: another entry of its tool was skipped.
 */
export type PermissionSkipReason = "invalid" | "rewritten" | "conflict" | "same-tool";

export interface PermissionsImportResult {
  /** Number of entries now managed. */
  added: number;
  /** Entries left in settings.json as they are (Kitroom does not manage their tool). */
  skipped: { entry: string; reason: PermissionSkipReason }[];
}

/** Starts managing the allow / ask / deny lists of the scope's settings.json. */
export async function importPermissions(ctx: PathContext): Promise<PermissionsImportResult> {
  if (await readManagedPermissions(ctx)) return { added: 0, skipped: [] };
  const r = new Reader();
  const path = claudeSettingsPath(ctx);
  const settings = (await r.json(path)) as { permissions?: Record<string, unknown> } | undefined;
  if (r.issues.length) throw new Error(`Could not read ${path}: ${r.issues[0]!.message}`);
  const lists = Object.fromEntries(
    PERMISSION_ACTIONS.map((a) => {
      const v = settings?.permissions?.[a];
      return [a, Array.isArray(v) ? v.filter((x): x is string => typeof x === "string") : []];
    }),
  ) as unknown as ManagedPermissions;

  const skipped: PermissionsImportResult["skipped"] = [];
  const count = new Map<string, number>();
  for (const a of PERMISSION_ACTIONS) for (const e of new Set(lists[a])) count.set(e, (count.get(e) ?? 0) + 1);
  const bad = new Set<string>();
  for (const [e, n] of count) {
    const problem = n > 1 ? "conflict" : permissionProblem(e);
    if (problem) {
      skipped.push({ entry: e, reason: problem });
      bad.add(e);
    }
  }
  // A tool Kitroom manages has all its entries replaced on apply, so a tool with any
  // entry that cannot be managed is left out entirely (its entries stay untouched).
  const badTools = new Set([...bad].map((e) => parsePermission(e)?.tool ?? e).map((t) => CANONICAL_TO_CLAUDE[categoryOf(t)] ?? t));
  const keep = (e: string) => !bad.has(e) && !badTools.has(CANONICAL_TO_CLAUDE[categoryOf(parsePermission(e)!.tool)] ?? parsePermission(e)!.tool);
  for (const a of PERMISSION_ACTIONS) {
    for (const e of new Set(lists[a])) if (!bad.has(e) && !keep(e)) skipped.push({ entry: e, reason: "same-tool" });
  }
  const managed: ManagedPermissions = { allow: [], ask: [], deny: [] };
  for (const a of PERMISSION_ACTIONS) managed[a] = [...new Set(lists[a])].filter(keep);
  const saved = await saveManagedPermissions(ctx, managed);
  return { added: saved.allow.length + saved.ask.length + saved.deny.length, skipped: skipped.sort((x, y) => x.entry.localeCompare(y.entry)) };
}

const sortedLists = (perms: unknown) => {
  const p = (perms && typeof perms === "object" ? perms : {}) as Record<string, unknown>;
  return PERMISSION_ACTIONS.map((a) => (Array.isArray(p[a]) ? [...(p[a] as unknown[])].map(String).sort() : []));
};

/**
 * Takes only the allow / ask / deny lists from rulesync's settings.json and puts
 * them into the user's file. Everything else rulesync might change (formatting,
 * a `$schema` key) stays as the user had it. Same lists in another order = no change.
 */
export function patchClaudeSettings(before: string | null, generated: string): string {
  const lists = ((JSON.parse(generated) as { permissions?: Record<string, unknown> }).permissions ?? {}) as Record<string, unknown>;
  const base = (before === null ? {} : JSON.parse(before)) as Record<string, unknown>;
  const perms = { ...((base.permissions as Record<string, unknown> | undefined) ?? {}) };
  for (const a of PERMISSION_ACTIONS) {
    const v = lists[a];
    if (Array.isArray(v) && v.length) perms[a] = v;
    else delete perms[a];
  }
  if (before !== null && JSON.stringify(sortedLists(base.permissions)) === JSON.stringify(sortedLists(perms))) return before;
  const next: Record<string, unknown> = { ...base, permissions: perms };
  if (Object.keys(perms).length === 0) delete next.permissions;
  // No rules and no file: nothing worth creating (the pipeline skips empty output).
  if (before === null && Object.keys(next).length === 0) return "";
  return `${JSON.stringify(next, null, 2)}\n`;
}

/** Entries in `before` that are not in `after` (removed by the apply). */
export function removedPermissions(before: string | null, after: string | null): string[] {
  try {
    const all = (text: string | null) => new Set(text === null ? [] : sortedLists((JSON.parse(text) as { permissions?: unknown }).permissions).flat());
    const kept = all(after);
    return [...all(before)].filter((e) => !kept.has(e)).sort();
  } catch {
    return [];
  }
}
